let REACT_FAIL=0;
async function react(node,destId,nav,transition){const action={type:'NODE',destinationId:destId,navigation:nav,transition:transition||null,preserveScrollPosition:false};const rx=[{trigger:{type:'ON_CLICK'},actions:[action]}];try{await node.setReactionsAsync(rx);}catch(e){try{node.reactions=[{trigger:{type:'ON_CLICK'},action}];}catch(e2){REACT_FAIL++;}}}
