const sW=mk(swatchRaw('white')),sD=mk(swatchRaw('dark'));set([sW,sD],'Color Swatch',1050,460);out.swWhite=sW;out.swDark=sD;
const bP=mk(btnRaw('Load','primary')),bG=mk(btnRaw('Reset to defaults','ghost'));set([bP,bG],'Button',1250,460);out.btnPrimary=bP;out.btnGhost=bG;
// search, user card
out.search=single(searchRaw('Search functions'),'Search Field',800,580);
out.user=single(userRaw(imgHash),'User Card',1100,580);
// nav + tab references
