const tbOff=AL('HORIZONTAL',{name:'State=Inactive',r:8,h:32,p:[0,16,0,16],cx:'CENTER'});tbOff.appendChild(T('Silent Aim',13,'m',C.ink3));
const tbOn=AL('HORIZONTAL',{name:'State=Active',fill:'#0F0F0F',stroke:'#2A2A2A',r:8,h:32,p:[0,16,0,16],cx:'CENTER'});tbOn.appendChild(T('Aimbot',13,'m',C.ink));
set([mk(tbOff),mk(tbOn)],'Tab',1350,700);
// icons
