// ---------- prototype wiring ----------
async function wirePrototype(){
 const names=Object.keys(SCREENS);
 const firstOf={};names.forEach(n=>{const page=n.split(' / ')[0];if(!firstOf[page])firstOf[page]=n;});
 for(const n of names){
  const sc=SCREENS[n];const page=n.split(' / ')[0];
  const frames=sc.findAllWithCriteria({types:['FRAME']});
  for(const f of frames){
   if(f.name.startsWith('Nav/')){const target=firstOf[f.name.slice(4)];if(target&&target!==n)await react(f,SCREENS[target].id,'NAVIGATE',null);}
   else if(f.name.startsWith('Tab/')){const target=page+' / '+f.name.slice(4);if(SCREENS[target]&&target!==n)await react(f,SCREENS[target].id,'NAVIGATE',null);}
  }
  const user=sc.findAllWithCriteria({types:['INSTANCE']}).find(i=>i.name==='User Card');
  if(user){const target=n==='Settings / Account popover'?'Settings':'Settings / Account popover';if(SCREENS[target])await react(user,SCREENS[target].id,'NAVIGATE',null);}
 }
 try{figma.currentPage.flowStartingPoints=[{nodeId:SCREENS['Aimbot / Aimbot'].id,name:'G7External'}];}catch(e){}
 try{figma.currentPage.prototypeBackgrounds=[S('#000000')];}catch(e){}
}

