root.appendChild(T('G7External · Brand',22,'s','#FFFFFF'));
const tiles=AL('HORIZONTAL',{name:'Logo tiles',gap:24});add(root,tiles,'FILL');
function tile(bg,name){const t=AL('HORIZONTAL',{name,fill:bg,stroke:'#2A2A2A',r:14,w:357,h:280,ax:'CENTER',cx:'CENTER'});tiles.appendChild(t);return t;}
const t1=tile('#000000','Logo on black');const l1=figma.createNodeFromSvg(LOGO_SVG);l1.rescale(300/700);l1.name='Logo / White';t1.appendChild(l1);
