async function main(){
  await Promise.all(Object.values(FONTS).map(f=>figma.loadFontAsync(f)));
  const screensPage=figma.createPage();screensPage.name='G7 · Screens';
  const compPage=figma.createPage();compPage.name='G7 · Components';
  const brandPage=figma.createPage();brandPage.name='G7 · Brand';
  figma.notify('G7External: building components…');
  const comps=await buildComponents(compPage);
  figma.notify('G7External: building screens…');
  await buildScreens(screensPage,comps);
  await wirePrototype();
  figma.notify('G7External: building brand sheet…');
  await buildBrand(brandPage);
  await figma.setCurrentPageAsync(screensPage);
  figma.viewport.scrollAndZoomIntoView(screensPage.children);
  figma.closePlugin('G7External: done — '+IDS.length+' screens built'+(REACT_FAIL?' ('+REACT_FAIL+' interactions could not be set)':'')+'. Press Present to click through.');
}
main().catch(e=>{figma.closePlugin('G7External build failed: '+(e&&e.message?e.message:e));});
